//! Matching an entity against a query request.

/// A query request that can test an entity in memory (equality, range and
/// substring filters).
///
/// Generated by `#[entity(matches)]`: every supplied filter must match the
/// entity; an empty query matches everything. Handy for tests and in-memory
/// repositories.
pub trait Filter<E> {
    fn matches(&self, entity: &E) -> bool;
}
